      *OHOS::DiskManager::PartitionTableInfo;

      # FormatParams - public data type (broad wildcard)
      *OHOS::DiskManager::FormatParams::*;
      *OHOS::DiskManager::FormatParams;
    };

    # C runtime symbols
    _init;
    _fini;

